using System.Text.RegularExpressions;using EnterpriseDocumentIntelligence.BuildingBlocks.Messaging;
public interface IChunker{IReadOnlyList<ChunkContract> Chunk(string text,int maxTokens=500,int overlapTokens=50);}
public sealed class SemanticChunker:IChunker{public IReadOnlyList<ChunkContract> Chunk(string text,int maxTokens=500,int overlapTokens=50){if(string.IsNullOrWhiteSpace(text))return [];if(maxTokens<50)throw new ArgumentOutOfRangeException(nameof(maxTokens));if(overlapTokens<0||overlapTokens>=maxTokens)throw new ArgumentOutOfRangeException(nameof(overlapTokens));var normalized=Regex.Replace(text.Replace("\\r"," "),"[ \\t]+"," ").Trim();var sentences=Regex.Split(normalized,"(?<=[.!?])\\s+").Where(x=>!string.IsNullOrWhiteSpace(x)).ToArray();var output=new List<ChunkContract>();var current=new List<string>();var count=0;foreach(var sentence in sentences){var words=sentence.Split(' ',StringSplitOptions.RemoveEmptyEntries);if(words.Length>maxTokens)for(var i=0;i<words.Length;i+=maxTokens){var part=string.Join(' ',words.Skip(i).Take(maxTokens));output.Add(new(Guid.NewGuid(),output.Count,part,part.Split(' ',StringSplitOptions.RemoveEmptyEntries).Length));}else if(count+words.Length>maxTokens&&current.Count>0){var chunk=string.Join(' ',current);output.Add(new(Guid.NewGuid(),output.Count,chunk,count));var overlap=current.TakeLast(Math.Min(overlapTokens,current.Count)).ToList();current=overlap;count=overlap.Count;current.AddRange(words);count+=words.Length;}else{current.Add(sentence);count+=words.Length;}}if(current.Count>0){var chunk=string.Join(' ',current);output.Add(new(Guid.NewGuid(),output.Count,chunk,count));}return output;}}